import org.eclipse.rdf4j.sail.SailException;
import org.eclipse.rdf4j.sail.lmdb.LmdbBackupDeltaCodec.Record;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Post-commit backup publisher that publishes backup records after the commit is complete and writer state is released.
 * This ensures backup publication never conflicts with resize/snapshot operations that need environment locks.
 * <p>
 * Records are queued during commit but only published after the writer is released, eliminating lock-order inversion
 * between backup publication and LMDB resize/copy operations.
 */
final class PostCommitBackupPublisher implements LmdbSailStore.CommitListener {

	private static final Logger logger = LoggerFactory.getLogger(PostCommitBackupPublisher.class);

	private final LmdbSailStore backingStore;
	private volatile LmdbBackupServiceImpl backupService;
	private final AtomicBoolean closed = new AtomicBoolean(false);

	PostCommitBackupPublisher(LmdbSailStore backingStore, LmdbBackupServiceImpl backupService) {
		this.backingStore = backingStore;
		if (backupService != null) {
			setBackupService(backupService);
		}
	}

	void setBackupService(LmdbBackupServiceImpl backupService) {
		this.backupService = backupService;
	}

	@Override
	public void onCommit(long transactionId, long previousRequiredTxn, List<Record> records) {
		if (closed.get()) {
			logger.debug("Backup publisher closed, skipping publication for txn {}", transactionId);
			return;
		}

		if (records == null || records.isEmpty()) {
			return;
		}

		logger.debug("Publishing backup delta for transaction {}, records: {}", transactionId, records.size());

		try {
			backupService.onCommit(transactionId, previousRequiredTxn, records);
			logger.debug("Successfully published backup delta for transaction {}", transactionId);
		} catch (RuntimeException | Error e) {
			logger.warn("Failed to publish backup delta for transaction {}", transactionId, e);
			try {
				backupService.onCommitFailure(transactionId, e);
			} catch (RuntimeException reportingFailure) {
				logger.warn("Failed to report backup publication failure", reportingFailure);
			}

			if (e instanceof Error error) {
				throw error;
			}

			// Continue processing other deltas even if one fails
		}
	}

	@Override
	public void onCommitFailure(long transactionId, long previousRequiredTxn, List<Record> records, Throwable error) {
		logger.warn("Backup publication failure for transaction {}", transactionId, error);
	}

	/**
	 * Signal that the publisher should stop.
	 */
	void close() {
		if (closed.getAndSet(true)) {
			return; // Already closed
		}

		logger.debug("Post-commit backup publisher closed");
	}

	/**
	 * Check if the publisher is closed.
	 *
	 * @return true if closed
	 */
	boolean isClosed() {
		return closed.get();
	}
}
